def __burn(amount: float):
    difference = __MaxSupply.get() - __MinSupply.get()
    if __balances[__BurnAddress.get()] < difference:
        amountToBurn = amount * __BurnRate.get()
        if amountToBurn <= __MaxBurn.get():
            return amount * __BurnRate.get()
        else:
            return __MaxBurn.get()
    else:
        return 0


